  status TEXT NOT NULL,
  acc_trans_id_fk BIGINT,
  comment VARCHAR(191),
  recorder_id BIGINT,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT tw_invoice_history_inv_type_check CHECK (inv_type IN ('r', 'u')),
  CONSTRAINT tw_invoice_history_status_check CHECK (status IN ('init', 'invoice', 'paid', 'owe', 'deleted'))
);

CREATE TABLE tw_invoice_temp (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  meter_id_fk BIGINT NOT NULL,
  inv_period_id_fk BIGINT NOT NULL,
  lastmeter NUMERIC(18,4) NOT NULL,
  currentmeter NUMERIC(18,4) NOT NULL,
  water_used NUMERIC(18,4) NOT NULL,
  inv_type TEXT NOT NULL,
  paid NUMERIC(18,4) NOT NULL,
  reserve_meter NUMERIC(18,4) NOT NULL,
  vat NUMERIC(18,4) NOT NULL,
  totalpaid NUMERIC(18,4) NOT NULL,
  status TEXT NOT NULL,
  acc_trans_id_fk BIGINT,
  comment VARCHAR(191),
  recorder_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT tw_invoice_temp_inv_type_check CHECK (inv_type IN ('r', 'u')),
  CONSTRAINT tw_invoice_temp_status_check CHECK (status IN ('init', 'invoice', 'paid', 'owe', 'deleted'))
);

CREATE TABLE tw_meter_infos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  meter_id BIGINT NOT NULL,
  org_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
  meternumber VARCHAR(191) NOT NULL,
  factory_no VARCHAR(191) NOT NULL,
  submeter_name VARCHAR(191),
  meter_address VARCHAR(191),
  undertake_zone_id BIGINT NOT NULL,
  undertake_subzone_id BIGINT NOT NULL,
  acceptance_date DATE NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  comment VARCHAR(191),
  metertype_id BIGINT,
  owe_count INTEGER NOT NULL DEFAULT 0,
  cutmeter TEXT NOT NULL DEFAULT '0',
  inv_no_index INTEGER DEFAULT 0,
  payment_id INTEGER NOT NULL DEFAULT 0,
  recorder_id INTEGER,
  last_meter_recording INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  old_meter_id INTEGER NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT tw_meter_infos_status_check CHECK (status IN ('active', 'inactive', 'deleted')),
  CONSTRAINT tw_meter_infos_cutmeter_check CHECK (cutmeter IN ('1', '0'))
);

CREATE TABLE tw_meter_type_rate_configs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  org_id BIGINT NOT NULL,
  meter_type_id_fk BIGINT NOT NULL,
  pricing_type_id BIGINT NOT NULL,
  tier_calculation_type SMALLINT NOT NULL DEFAULT 1,
  min_usage_charge NUMERIC(18,4),
  charge_min_only_zero_use SMALLINT NOT NULL DEFAULT 0,
  vat NUMERIC(18,4) NOT NULL DEFAULT 0,
  fixed_rate_per_unit NUMERIC(18,4),
  effective_date DATE NOT NULL,
  end_date DATE,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  comment TEXT,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

CREATE TABLE tw_meter_type_rate_tiers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  meter_type_rate_config_id BIGINT NOT NULL,
  min_units INTEGER NOT NULL,
  max_units INTEGER,
  rate_per_unit NUMERIC(18,4) NOT NULL,
  tier_order INTEGER NOT NULL,
  comment TEXT,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT tier_order_unique_per_config UNIQUE (meter_type_rate_config_id, tier_order)
);

CREATE TABLE tw_meter_types (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  org_id BIGINT,
