  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

CREATE TABLE tw_notifies (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id BIGINT,
  org_id VARCHAR(191),
  reporter_name VARCHAR(191) NOT NULL,
  reporter_phone VARCHAR(191) NOT NULL,
  issue_type_id BIGINT NOT NULL,
  description TEXT,
  latitude NUMERIC(10,8) NOT NULL,
  longitude NUMERIC(11,8) NOT NULL,
  photo_path VARCHAR(191),
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT tw_notifies_status_check CHECK (status IN ('pending', 'processing', 'complete', 'cancel'))
);

CREATE TABLE tw_notify_staff (
  notify_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
