  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

CREATE TABLE user_meter_infos (
  meter_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
  meternumber VARCHAR(191) NOT NULL,
  metertype_id BIGINT,
  meter_address VARCHAR(20),
  undertake_zone_id INTEGER,
  undertake_subzone_id INTEGER,
  acceptance_date DATE,
  payment_id INTEGER,
  owe_count INTEGER NOT NULL DEFAULT 0,
  cutmeter INTEGER NOT NULL DEFAULT 0,
  inv_no INTEGER NOT NULL DEFAULT 1,
  comment TEXT,
  recorder_id INTEGER NOT NULL DEFAULT 1,
  discounttype INTEGER,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (meter_id),
  CONSTRAINT user_meter_infos_status_check CHECK (status IN ('active', 'inactive', 'changemeter', 'deleted', 'cutmeter', 'permanent deleted'))
);

CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  org_id BIGINT,
  username VARCHAR(191),
  password VARCHAR(191),
  prefix VARCHAR(191),
  firstname VARCHAR(191),
  lastname VARCHAR(191),
  email VARCHAR(191),
  zone_id BIGINT NOT NULL,
  subzone_id BIGINT NOT NULL,
  tambon_code BIGINT NOT NULL,
  district_code BIGINT NOT NULL,
  province_code BIGINT NOT NULL,
  age INTEGER NOT NULL DEFAULT 0,
  weight DOUBLE PRECISION NOT NULL DEFAULT 0,
  height DOUBLE PRECISION NOT NULL DEFAULT 0,
  gender TEXT,
  line_id VARCHAR(191),
  line_user_id VARCHAR(191),
  id_card VARCHAR(191),
  phone VARCHAR(191),
  image TEXT,
  address VARCHAR(191),
  email_verified_at TIMESTAMPTZ,
  remember_token VARCHAR(100),
  status TEXT DEFAULT 'active',
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  old_id INTEGER NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT users_email_unique UNIQUE (email),
  CONSTRAINT users_gender_check CHECK (gender IN ('m', 'w')),
  CONSTRAINT users_status_check CHECK (status IN ('active', 'inactive', 'deleted'))
);

CREATE TABLE zones (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  zone_name VARCHAR(191) NOT NULL,
  location TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  tambon_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  org_id BIGINT NOT NULL,
  lat VARCHAR(191) NOT NULL,
  long VARCHAR(191) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT zones_status_check CHECK (status IN ('active', 'inactive'))
);

